    # its four corner markers agree; otherwise it takes the interior background.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Find boundary rows and columns by frequent near-uniform color.
    rows = [r for r in range(h) if len(set(grid[r])) <= 2 and max(Counter(grid[r]).values()) >= w - 2]
    cols = [c for c in range(w) if max(Counter(grid[r][c] for r in range(h)).values()) >= h - 2]
    if len(rows) < 2 or len(cols) < 2:
        return [[bg]]
    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]]
            line.append(corners[0] if len(set(corners)) == 1 else bg)
